/* B"H — mobile panels: compact reachable top/bottom vessels */
@media (max-width: 680px) {
  .sidebar,
  .automation-panel {
    display: grid !important;
    position: relative !important;
    inset: auto !important;
    min-width: 0 !important;
    width: 100% !important;
    max-width: none !important;
    border-radius: 18px !important;
    overflow: hidden !important;
    z-index: auto !important;
  }
  .sidebar { grid-area: left !important; max-height: 84px !important; grid-template-rows: 72px minmax(0, 1fr) !important; }
  .automation-panel { grid-area: right !important; max-height: 90px !important; grid-template-rows: 76px minmax(0, 1fr) !important; }
  body:not([data-sidebar-collapsed="true"]) .sidebar { max-height: min(42dvh, 360px) !important; }
  body:not([data-automation-collapsed="true"]) .automation-panel { max-height: min(48dvh, 420px) !important; }
  .panel-topbar,
  .sidebar-header {
    min-height: 68px !important;
    padding: 10px 12px !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
  }
  .sidebar::before,
  .automation-panel::before {
    writing-mode: horizontal-tb !important;
    transform: none !important;
    position: static !important;
  }
  .conversation-list,
  .automation-panel > :not(.panel-topbar) {
    min-height: 0 !important;
    overflow: auto !important;
    padding: 10px !important;
  }
  body[data-sidebar-collapsed="true"] .conversation-list,
  body[data-automation-collapsed="true"] .automation-panel > :not(.panel-topbar) { display: none !important; }
  body[data-sidebar-collapsed="true"] .sidebar,
  body[data-automation-collapsed="true"] .automation-panel { max-height: 76px !important; }
  .panel-action-rail,
  .panel-corner-actions { position: static !important; transform: none !important; }
  .right-tabs { overflow-x: auto !important; flex-wrap: nowrap !important; }
  .right-tabs button { flex: 0 0 auto !important; min-width: 104px !important; }
}
